function buildChapters() {
  const challengeIdsByChapter = buildChapterChallengeIds();
  return COURSE_CHAPTERS.map((chapter) => ({
    id: chapter.id,
    title: chapter.title,
    linkedChallenges: [...(challengeIdsByChapter.get(chapter.id) ?? [])],
    ...CHAPTER_CONTENT[chapter.id],
  }));
}

export const COURSEWARE = Object.freeze({
  title: "计算机组成原理",
  textbook: "杨泽雪《计算机组成原理》，机械工业出版社，2021",
  references: [
    "唐朔飞《计算机组成原理 (第3版)》，高等教育出版社，2021",
    "戴维.A《计算机组成与设计-硬件与软件接口》，机械工业出版社，2020",
    "茱莉亚洛博《计算机组成与体系结构》，机械工业出版社，2020",
  ],
  chapters: buildChapters(),
});

export function getCoursewareChapter(chapterId) {
  return COURSEWARE.chapters.find((chapter) => chapter.id === chapterId) ?? null;
}

export function getChallengesByChapter(chapterId) {
  return getCoursewareChapter(chapterId)?.linkedChallenges ?? [];
}

